MOD = 10**9 + 7

def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    s = input[ptr]

    balance = 0
    min_balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        min_balance = min(min_balance, balance)

    if balance < 0 or (n - m) % 2 != -balance:
        print(0)
        return

    k = (n - m) // 2
    if balance < 0:
        k += balance

    dp = [[0] * (k + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for i in range(k + 1):
        for j in range(k + 1):
            if dp[i][j] == 0:
                continue
            if i < k:
                dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD
            if j < k:
                dp[i][j + 1] = (dp[i][j + 1] + dp[i][j]) % MOD

    res = dp[k][k]
    if min_balance < 0:
        res = 0

    print(res)

solve()
